    {
      "name": "cycle_time_budget",
      "value": "23.0",
      "units": "s",
      "narrative_section": "4.8"
    }
  ],
  "steps": [
    {
      "name": "IDLE / START",
      "entry": "Initial state or pallet departure clears previous cycle",
      "exit": "Pallet arrives at test position (ZS-2008 rising edge) AND cell in auto mode (SS-0003) AND no ST20 fault active (M299 OFF) AND station idle (M200 OFF)"
    },
    {
      "name": "CLAMP",
      "entry": "Start conditions met; M201 SET, clamp solenoid XY-2002 energized",
      "exit": "Clamp confirmed closed (ZS-2002A made) AND clamp open switch clear (ZS-2002B clear)"
    },
    {
      "name": "FILL",
      "entry": "Clamp confirmed closed; M202 SET, fill valve XV-2003 opens",
      "exit": "PT-2001 reaches fill complete threshold (14.50 kPa / D122) OR fill timeout occurs (8.0 s / T21)"
    },
    {
      "name": "STABILISE",
      "entry": "Fill complete threshold reached; M203 SET, fill valve closed, stabilisation timer started",
      "exit": "Stabilisation timer expires"
    },
    {
      "name": "TEST",
      "entry": "Stabilisation complete and baseline pressure recorded; M204 SET, test window timer started",
      "exit": "Test window timer expires (10.0 s / T23)"
    },
    {
      "name": "VENT",
      "entry": "Test window complete OR abort due to fault/alarm/fill timeout; M205 SET, vent valve XV-2004 opens",
      "exit": "Vent timer expires AND pack pressure vented below 1.00 kPa AND PT-2001 pressure signal healthy"
    },
    {
      "name": "UNCLAMP",
      "entry": "Vent conditions satisfied; M206 SET, clamp solenoid XY-2002 de-energized",
      "exit": "Clamp confirmed open (ZS-2002B made AND ZS-2002A clear)"
    },
    {
      "name": "DONE",
      "entry": "Clamp confirmed open; M207 SET, PASS (Y23) or FAIL (Y24) signal presented to line controller",
      "exit": "Pallet leaves test position (ZS-2008 clear); station resets to idle"
    }
  ],
  "interlocks": [
    {
      "cause": "Station busy (M200 ON)",
      "effect": "Pallet arrival sensor dropping and returning is ignored and cannot restart cycle"
    },
    {
      "cause": "Clamp closed confirmation (ZS-2002A) lost or open confirmation (ZS-2002B) made during FILL",
      "effect": "Fill valve XV-2003 closes immediately"
    },
    {
      "cause": "Pack pressure not below 1.00 kPa or PT-2001 signal fault active",
      "effect": "Station holds in VENT with vent valve open; unclamp is inhibited"
    },
    {
      "cause": "Station not at DONE step",
      "effect": "PASS (RS-2006) and FAIL (RS-2007) signals to line controller are withheld"
    },
    {
      "cause": "Cell in auto mode (X2 ON)",
      "effect": "Manual vent pushbutton PB-2010 (X25) is inhibited from opening vent valve XV-2004"
    },
    {
      "cause": "E-stop chain lost (X0 OFF) or any ST20 alarm active while busy",
      "effect": "Cycle aborts immediately to VENT with FAIL result latched"
    },
    {
      "cause": "Over-pressure trip (PT-2001 > 20.00 kPa)",
      "effect": "Fill valve closes immediately, vent valve held open, cycle fails"
    },
    {
      "cause": "PT-2001 wire break / reading below -5.00 kPa",
      "effect": "Cycle start is inhibited and clamp release is held"
    },
    {
      "cause": "Supply air pressure switch PS-2009 lost while busy",
      "effect": "Cycle aborts to VENT with FAIL result latched"
    }
  ],
  "alarms": [
    {
      "name": "Fill timeout",
      "condition": "PT-2001 does not reach 14.50 kPa within 8.0 s during FILL step (T21 done)",
      "action": "Latches M290, lights fault beacon HL-2011, aborts cycle to VENT, and sets FAIL result"
    },
    {
      "name": "Over-pressure",
      "condition": "PT-2001 reading exceeds 20.00 kPa (D100 > D123 / K2000)",
      "action": "Latches M291, lights fault beacon HL-2011, forces fill valve closed, holds vent valve open, and sets FAIL result"
    },
    {
      "name": "PT-2001 signal fault",
      "condition": "PT-2001 reading falls below -5.00 kPa (D100 < K-500, indicating wire break)",
      "action": "Sets M292, lights fault beacon HL-2011, inhibits cycle start, and holds unclamp in VENT"
    },
    {
      "name": "Supply air low",
      "condition": "PS-2009 lost (X22 OFF) while station is busy (M200 ON)",
      "action": "Latches M293, lights fault beacon HL-2011, aborts cycle to VENT, and sets FAIL result"
    }
  ],
  "conflicts": [
    {
      "item": "stabilise_time",
      "narrative_says": "3 s (Section 4.4)",
      "parameter_sheet_says": "5.0 s (T22, changed from 3.0 s by MOC-2021-044)",
      "program_says": "5.0 s (R13 executes OUT T22 K50 with 100 ms timer base = 5.0 s)",
      "authoritative": "parameter sheet"
    },
    {
      "item": "vent_time",
      "narrative_says": "0.5 s (Section 4.7)",
      "parameter_sheet_says": "0.5 s (T24)",
      "program_says": "5.0 s (R21 executes OUT T200 K50; on FX5U standard timers are 100 ms, so K50 yields 5.0 s instead of FX3U 10 ms 0.5 s, and uses T200 instead of T24)",
      "authoritative": "parameter sheet"
    },
    {
      "item": "test_pressure",
      "narrative_says": "15.2 kPa (Section 4.3)",
      "parameter_sheet_says": "15.00 kPa(g) (note specifies supply regulator set to 15.2 kPa)",
      "program_says": "Not configured in PLC registers (mechanical regulator PR-2012)",
      "authoritative": "parameter sheet"
    }
  ]
}
